import webpush from 'web-push';
import { env } from '../env.js';
import { prisma } from '../db.js';

export const pushConfigured = Boolean(env.vapidPublicKey && env.vapidPrivateKey);

if (pushConfigured) {
  webpush.setVapidDetails(env.vapidSubject, env.vapidPublicKey, env.vapidPrivateKey);
}

// Real web push — no third-party account needed, just the VAPID keypair
// generated by `npm run vapid:generate`. Works today, not "once credentials
// arrive."
export async function notifyFan(fanId, payload) {
  if (!pushConfigured) return { ok: false, reason: 'VAPID keys not configured' };
  const subs = await prisma.pushSubscription.findMany({ where: { fanId } });
  const results = await Promise.allSettled(
    subs.map((s) =>
      webpush.sendNotification(
        { endpoint: s.endpoint, keys: { p256dh: s.p256dh, auth: s.auth } },
        JSON.stringify(payload)
      )
    )
  );
  // A 410/404 means the subscription is dead — prune it so we stop paying the round trip.
  await Promise.all(
    results.map((r, i) => {
      if (r.status === 'rejected' && [404, 410].includes(r.reason?.statusCode)) {
        return prisma.pushSubscription.delete({ where: { id: subs[i].id } }).catch(() => {});
      }
    })
  );
  return { ok: true, sent: results.filter((r) => r.status === 'fulfilled').length, total: subs.length };
}

export async function notifyAllFans(payload) {
  const subs = await prisma.pushSubscription.findMany();
  const results = await Promise.allSettled(
    subs.map((s) =>
      webpush.sendNotification(
        { endpoint: s.endpoint, keys: { p256dh: s.p256dh, auth: s.auth } },
        JSON.stringify(payload)
      )
    )
  );
  return { ok: true, sent: results.filter((r) => r.status === 'fulfilled').length, total: subs.length };
}
